begin;
create table public.club_catalog_categories (
 id integer primary key,name text not null,parent_id integer,slug text not null unique,source_url text not null,
 position integer not null default 0,active boolean not null default true
);
create table public.club_catalog_products (
 product_id uuid primary key references public.prodotti(id),display_name text not null,description text not null default '',
 visible boolean not null default true,website_url text,classification_source text not null default 'workspace' check(classification_source in ('workspace','website','manual')),
 updated_at timestamptz not null default clock_timestamp()
);
create table public.club_catalog_product_categories (
 product_id uuid references public.club_catalog_products(product_id) on delete cascade,category_id integer references public.club_catalog_categories(id),primary key(product_id,category_id)
);
create table public.club_catalog_product_media (
 product_id uuid references public.club_catalog_products(product_id) on delete cascade,document_id uuid references public.documenti_workspace(id),
 position integer not null default 0,is_cover boolean not null default false,primary key(product_id,document_id)
);
create unique index club_catalog_cover_unique on public.club_catalog_product_media(product_id) where is_cover;
create table public.club_posts (
 id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('news','offer','communication')),
 title text not null check(length(btrim(title)) between 1 and 180),summary text not null default '' check(length(summary)<=500),
 body text not null check(length(btrim(body)) between 1 and 30000),audience text not null default 'all' check(audience in ('all','members','stores','staff')),
 status text not null default 'draft' check(status in ('draft','published','archived')),featured boolean not null default false,
 starts_at timestamptz not null default now(),ends_at timestamptz,created_by uuid not null references public.utenti(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default clock_timestamp(),published_at timestamptz,
 check(ends_at is null or ends_at>starts_at)
);
create index club_posts_public_idx on public.club_posts(status,audience,kind,starts_at desc);
create table public.club_post_media (
 post_id uuid references public.club_posts(id) on delete cascade,document_id uuid references public.documenti_workspace(id),
 position integer not null default 0,is_cover boolean not null default false,primary key(post_id,document_id)
);
create unique index club_post_cover_unique on public.club_post_media(post_id) where is_cover;
create table public.club_post_products (
 post_id uuid references public.club_posts(id) on delete cascade,product_id uuid references public.prodotti(id),primary key(post_id,product_id)
);
do $$declare t text;begin
 foreach t in array array['club_catalog_categories','club_catalog_products','club_catalog_product_categories','club_catalog_product_media','club_posts','club_post_media','club_post_products'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;
