('crm.online.club.contenuti','Club · Novità e comunicazioni','Novità, offerte e comunicazioni pubblicate nell’app.','workspace','/crm/online/salidischiaclub/contenuti','crm.club.contenuti',false,true,498,'crm','megaphone','{"crm_area":"SalidischiaClub","parent_path":"/crm/online"}',now());
insert into public.workspace_moduli_schermate(modulo_codice,schermata_codice,ordine,predefinita,visibile_menu) values('crm_online','crm.online.club.catalogo',497,false,true),('crm_online','crm.online.club.contenuti',498,false,true);

create function public.club_catalog_eligible(p public.prodotti) returns boolean language sql immutable as $$
 select p.attivo_mexal is true and p.mostra_in_app is true and upper(btrim(coalesce(p.codice_mexal,''))) like 'IT%'
 and coalesce(to_jsonb(p)->>'linea_mexal','') not ilike '%fuori produzione%';
$$;
insert into public.club_catalog_products(product_id,display_name,description)
select id,nome,'' from public.prodotti p where public.club_catalog_eligible(p);

create function public.club_content_audiences() returns text[] language sql stable security definer set search_path=public as $$
 select array['all']||case
 when public.workspace_internal_user() and not public.club_external_identity() and public.crm_has_module_level('crm_online','lettura') then
  case when public.club_staff_allowed('contenuti') then array['members','stores','staff'] else array['staff'] end
 when exists(select 1 from public.club_members where auth_user_id=auth.uid() and active) then array['members']
 when public.club_store_code() is not null then array['stores'] else '{}'::text[] end;
$$;
create function public.club_catalog_categories() returns jsonb language sql stable security definer set search_path=public as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'parent_id',parent_id,'slug',slug) order by position,name,id),'[]') from public.club_catalog_categories where active;
$$;
create function public.club_catalog_product_json(target_id uuid,full_text boolean default false) returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('id',p.id,'name',c.display_name,'code',p.codice_mexal,
 'description',case when full_text then c.description else left(c.description,220) end,'website_url',c.website_url,
 'image_url',case when coalesce(to_jsonb(p)->>'immagine_catalogo_url',to_jsonb(p)->>'immagine_url','') ~ '^https://' then coalesce(to_jsonb(p)->>'immagine_catalogo_url',to_jsonb(p)->>'immagine_url') else null end,
 'category_ids',coalesce((select jsonb_agg(category_id order by category_id) from public.club_catalog_product_categories where product_id=p.id),'[]'),
 'media',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'title',d.titolo,'kind',d.mime_group,'cover',m.is_cover) order by m.is_cover desc,m.position,d.titolo)
 from public.club_catalog_product_media m join public.documenti_workspace d on d.id=m.document_id where m.product_id=p.id and d.attivo),'[]'))
 from public.prodotti p join public.club_catalog_products c on c.product_id=p.id where p.id=target_id and c.visible and public.club_catalog_eligible(p);
$$;
create function public.club_catalog_products(search_text text default '',category_id integer default null,page_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 if length(search_text)>200 or page_offset<0 then raise exception 'Ricerca non valida.';end if;
 return (with recursive categories(id) as (select c.id from public.club_catalog_categories c where c.id=category_id and c.active union select c.id from public.club_catalog_categories c join categories parent on c.parent_id=parent.id where c.active),
 category_labels(product_id,id,name,parent_id) as (select pc.product_id,c.id,c.name,c.parent_id from public.club_catalog_product_categories pc join public.club_catalog_categories c on c.id=pc.category_id union select l.product_id,c.id,c.name,c.parent_id from category_labels l join public.club_catalog_categories c on c.id=l.parent_id),
 filtered as materialized(select p.id,c.display_name,p.codice_mexal from public.prodotti p join public.club_catalog_products c on c.product_id=p.id
 where c.visible and public.club_catalog_eligible(p) and (category_id is null or exists(select 1 from public.club_catalog_product_categories pc where pc.product_id=p.id and pc.category_id in(select id from categories)))
 and not exists(select 1 from unnest(regexp_split_to_array(lower(btrim(coalesce(search_text,''))),'\s+')) word where word<>'' and position(word in lower(concat_ws(' ',c.display_name,c.description,p.codice_mexal,to_jsonb(p)->>'ean',(select string_agg(cl.name,' ') from category_labels cl where cl.product_id=p.id))))=0))
 select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(public.club_catalog_product_json(id) order by display_name,codice_mexal,id) from(select * from filtered order by display_name,codice_mexal,id limit 24 offset page_offset)x),'[]')));
end $$;
create function public.club_catalog_product(target_id uuid) returns jsonb language sql stable security definer set search_path=public as $$select public.club_catalog_product_json(target_id,true)$$;
create function public.club_post_json(target_id uuid) returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('id',p.id,'kind',p.kind,'title',p.title,'summary',p.summary,'body',p.body,'featured',p.featured,'starts_at',p.starts_at,'ends_at',p.ends_at,
 'media',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'title',d.titolo,'kind',d.mime_group,'cover',m.is_cover) order by m.is_cover desc,m.position,d.titolo) from public.club_post_media m join public.documenti_workspace d on d.id=m.document_id where m.post_id=p.id and d.attivo),'[]'),
 'products',coalesce((select jsonb_agg(public.club_catalog_product_json(pp.product_id)) filter(where public.club_catalog_product_json(pp.product_id) is not null) from public.club_post_products pp where pp.post_id=p.id),'[]'))
 from public.club_posts p where p.id=target_id and p.status='published' and p.starts_at<=now() and (p.ends_at is null or p.ends_at>now()) and p.audience=any(public.club_content_audiences());
$$;
create function public.club_feed(content_kind text default '',page_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 if page_offset<0 or coalesce(content_kind,'') not in ('','news','offer','communication','highlights') then raise exception 'Filtro contenuti non valido.';end if;
 return (with filtered as materialized(select p.* from public.club_posts p where p.status='published' and p.starts_at<=now() and (p.ends_at is null or p.ends_at>now()) and p.audience=any(public.club_content_audiences()) and (coalesce(content_kind,'')='' or p.kind=content_kind or (content_kind='highlights' and p.kind in ('news','offer'))))
 select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(public.club_post_json(id)-'body'-'products' order by featured desc,starts_at desc,id) from(select * from filtered order by featured desc,starts_at desc,id limit 12 offset page_offset)x),'[]')));
end $$;
create function public.club_post(target_id uuid) returns jsonb language sql stable security definer set search_path=public as $$select public.club_post_json(target_id)$$;

create function public.club_editor_data(editor_kind text,search_text text default '',page_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 if editor_kind not in ('products','posts') or length(search_text)>200 or page_offset<0 then raise exception 'Ricerca editor non valida.';end if;
 perform public.club_require_staff(case when editor_kind='products' then 'catalogo' else 'contenuti' end);
 if editor_kind='products' then
  return (with filtered as materialized(select p.id,p.codice_mexal as code,coalesce(c.display_name,p.nome) as name,coalesce(c.visible,false) as visible,c.updated_at,c.classification_source,
    coalesce((select jsonb_agg(category_id) from public.club_catalog_product_categories where product_id=p.id),'[]') as category_ids
   from public.prodotti p left join public.club_catalog_products c on c.product_id=p.id where public.club_catalog_eligible(p) and concat_ws(' ',p.nome,p.codice_mexal,c.display_name) ilike '%'||search_text||'%')
   select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(to_jsonb(x) order by name,id) from(select * from filtered order by name,id limit 25 offset page_offset)x),'[]')));
 end if;
 return (with filtered as materialized(select * from public.club_posts where concat_ws(' ',title,summary,body) ilike '%'||search_text||'%')
 select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(to_jsonb(x) order by created_at desc,id) from(select * from filtered order by created_at desc,id limit 25 offset page_offset)x),'[]')));
end $$;
create function public.club_editor_entry(editor_kind text,target_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 if editor_kind='products' then
  perform public.club_require_staff('catalogo');
  select jsonb_build_object('id',p.id,'name',coalesce(c.display_name,p.nome),'description',coalesce(c.description,''),'code',p.codice_mexal,'visible',coalesce(c.visible,false),'website_url',c.website_url,'updated_at',c.updated_at,
   'category_ids',coalesce((select jsonb_agg(category_id) from public.club_catalog_product_categories where product_id=p.id),'[]'),
   'media',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'title',d.titolo,'kind',d.mime_group,'cover',m.is_cover) order by m.position) from public.club_catalog_product_media m join public.documenti_workspace d on d.id=m.document_id where m.product_id=p.id),'[]')) into result
  from public.prodotti p left join public.club_catalog_products c on c.product_id=p.id where p.id=target_id and public.club_catalog_eligible(p);
 elsif editor_kind='posts' then
  perform public.club_require_staff('contenuti');
  select to_jsonb(p)||jsonb_build_object('media',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'title',d.titolo,'kind',d.mime_group,'cover',m.is_cover) order by m.position) from public.club_post_media m join public.documenti_workspace d on d.id=m.document_id where m.post_id=p.id),'[]'),'product_ids',coalesce((select jsonb_agg(product_id) from public.club_post_products where post_id=p.id),'[]'),'products',coalesce((select jsonb_agg(jsonb_build_object('id',pp.product_id,'name',c.display_name,'code',pr.codice_mexal)) from public.club_post_products pp join public.club_catalog_products c on c.product_id=pp.product_id join public.prodotti pr on pr.id=pp.product_id where pp.post_id=p.id),'[]')) into result from public.club_posts p where p.id=target_id;
 else raise exception 'Editor non valido.';end if;
 return result;
end $$;
create function public.club_editor_media(search_text text default '',target_product_id uuid default null,page_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 if not(public.club_staff_allowed('catalogo') or public.club_staff_allowed('contenuti')) then raise exception 'Libreria Club non autorizzata.' using errcode='42501';end if;
 if length(search_text)>200 or page_offset<0 then raise exception 'Ricerca materiali non valida.';end if;
 return(with filtered as materialized(select d.id,d.titolo as title,d.mime_group as kind,s.nome as section,
 (d.prodotto_id=target_product_id or exists(select 1 from public.prodotti p where p.id=target_product_id and (lower(p.categoria_mexal)=any(select lower(x) from unnest(d.categorie_prodotto)x) or lower(p.brand_mexal)=any(select lower(x) from unnest(d.brand_prodotti)x) or lower(p.linea_mexal)=any(select lower(x) from unnest(d.linee_prodotto)x)))) as suggested
 from public.documenti_workspace d left join public.sezioni_documentali s on s.id=d.sezione_id where d.attivo and d.mime_group in ('pdf','immagine','video','altro') and concat_ws(' ',d.titolo,d.nome_file,s.nome) ilike '%'||search_text||'%')
 select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(to_jsonb(x) order by suggested desc nulls last,title,id) from(select * from filtered order by suggested desc nulls last,title,id limit 25 offset page_offset)x),'[]')));
end $$;

create function public.club_editor_products(search_text text default '',page_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 perform public.club_require_staff('contenuti');
 if length(search_text)>200 or page_offset<0 then raise exception 'Ricerca prodotti non valida.';end if;
 return(with filtered as materialized(select p.id,p.codice_mexal as code,c.display_name as name from public.prodotti p join public.club_catalog_products c on c.product_id=p.id where public.club_catalog_eligible(p) and concat_ws(' ',p.nome,p.codice_mexal,c.display_name) ilike '%'||search_text||'%') select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(to_jsonb(x) order by name,id) from(select * from filtered order by name,id limit 25 offset page_offset)x),'[]')));
end $$;
create function public.club_validate_media(ids uuid[],cover_id uuid) returns void language plpgsql stable security definer set search_path=public as $$
begin
 if coalesce(cardinality(ids),0)>40 or (cover_id is not null and (not cover_id=any(ids) or not exists(select 1 from public.documenti_workspace where id=cover_id and attivo and mime_group='immagine'))) then raise exception 'La copertina deve essere una foto Workspace selezionata.';end if;
 if exists(select 1 from unnest(ids) value where not exists(select 1 from public.documenti_workspace where id=value and attivo)) then raise exception 'Uno dei materiali selezionati non è più disponibile.';end if;
end $$;
create function public.club_save_catalog_product(target_id uuid,payload jsonb,expected_updated_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$
declare current_row public.club_catalog_products;ids uuid[];categories integer[];cover_id uuid;begin
 perform public.club_require_staff('catalogo','scrittura');
 if not exists(select 1 from public.prodotti p where p.id=target_id and public.club_catalog_eligible(p)) then raise exception 'Prodotto Workspace non disponibile.';end if;
 select * into current_row from public.club_catalog_products where product_id=target_id for update;
 if found and (expected_updated_at is null or current_row.updated_at<>expected_updated_at) then raise exception 'Il prodotto è cambiato. Ricarica prima di salvare.' using errcode='40001';end if;
 if length(btrim(payload->>'name')) not between 1 and 250 or length(coalesce(payload->>'description',''))>30000 then raise exception 'Controlla titolo e descrizione.';end if;
 select coalesce(array_agg(distinct value::uuid),'{}') into ids from jsonb_array_elements_text(coalesce(payload->'document_ids','[]'));
 select coalesce(array_agg(distinct value::integer),'{}') into categories from jsonb_array_elements_text(coalesce(payload->'category_ids','[]'));
 cover_id:=nullif(payload->>'cover_id','')::uuid;perform public.club_validate_media(ids,cover_id);
 if exists(select 1 from unnest(categories) value where not exists(select 1 from public.club_catalog_categories where id=value and active)) then raise exception 'Categoria non valida.';end if;
 insert into public.club_catalog_products(product_id,display_name,description,visible,classification_source,updated_at) values(target_id,btrim(payload->>'name'),coalesce(payload->>'description',''),coalesce((payload->>'visible')::boolean,false),'manual',clock_timestamp())
 on conflict(product_id) do update set display_name=excluded.display_name,description=excluded.description,visible=excluded.visible,classification_source='manual',updated_at=excluded.updated_at;
 delete from public.club_catalog_product_categories where product_id=target_id;
 insert into public.club_catalog_product_categories select target_id,value from unnest(categories)value;
 delete from public.club_catalog_product_media where product_id=target_id;
 insert into public.club_catalog_product_media select target_id,value,ordinality::integer,coalesce(value=cover_id,false) from unnest(ids)with ordinality as x(value,ordinality);
 perform public.club_audit_event('CATALOG_PRODUCT_SAVED',target_id);return target_id;
end $$;
create function public.club_save_post(payload jsonb,target_id uuid default null,expected_updated_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$
declare current_row public.club_posts;saved_post_id uuid:=coalesce(target_id,gen_random_uuid());ids uuid[];products uuid[];cover_id uuid;begin
 perform public.club_require_staff('contenuti','scrittura');
 if target_id is not null then
  select * into current_row from public.club_posts where id=target_id for update;
  if not found then raise exception 'Contenuto non trovato.';end if;
  if current_row.status='published' then raise exception 'Crea una nuova bozza per modificare un contenuto pubblicato.';end if;
  if expected_updated_at is null or current_row.updated_at<>expected_updated_at then raise exception 'Il contenuto è cambiato. Ricarica prima di salvare.' using errcode='40001';end if;
 end if;
 select coalesce(array_agg(distinct value::uuid),'{}') into ids from jsonb_array_elements_text(coalesce(payload->'document_ids','[]'));
 select coalesce(array_agg(distinct value::uuid),'{}') into products from jsonb_array_elements_text(coalesce(payload->'product_ids','[]'));
 cover_id:=nullif(payload->>'cover_id','')::uuid;perform public.club_validate_media(ids,cover_id);
 if exists(select 1 from unnest(products) value where not exists(select 1 from public.club_catalog_products where product_id=value)) then raise exception 'Prodotto collegato non valido.';end if;
 insert into public.club_posts(id,kind,title,summary,body,audience,featured,starts_at,ends_at,created_by,updated_at) values(saved_post_id,payload->>'kind',btrim(payload->>'title'),coalesce(payload->>'summary',''),btrim(payload->>'body'),coalesce(payload->>'audience','all'),coalesce((payload->>'featured')::boolean,false),coalesce(nullif(payload->>'starts_at','')::timestamptz,now()),nullif(payload->>'ends_at','')::timestamptz,public.workspace_current_profile_id(),clock_timestamp())
 on conflict(id) do update set kind=excluded.kind,title=excluded.title,summary=excluded.summary,body=excluded.body,audience=excluded.audience,featured=excluded.featured,starts_at=excluded.starts_at,ends_at=excluded.ends_at,status='draft',updated_at=excluded.updated_at;
 delete from public.club_post_media where club_post_media.post_id=saved_post_id;
 insert into public.club_post_media select saved_post_id,value,ordinality::integer,coalesce(value=cover_id,false) from unnest(ids)with ordinality as x(value,ordinality);
 delete from public.club_post_products where club_post_products.post_id=saved_post_id;
 insert into public.club_post_products select saved_post_id,value from unnest(products)value;
 perform public.club_audit_event('CONTENT_DRAFT_SAVED',saved_post_id);return saved_post_id;
end $$;
create function public.club_publish_post(target_id uuid,expected_updated_at timestamptz,archive boolean default false) returns void language plpgsql security definer set search_path=public as $$
declare row public.club_posts;begin
 perform public.club_require_staff('contenuti','amministrazione');
 select * into row from public.club_posts where id=target_id for update;
 if not found then raise exception 'Contenuto non trovato.';end if;
 if expected_updated_at is null or row.updated_at<>expected_updated_at then raise exception 'Il contenuto è cambiato. Ricarica prima di pubblicare.' using errcode='40001';end if;
 update public.club_posts set status=case when archive then 'archived' else 'published' end,published_at=case when archive then published_at else now() end,updated_at=clock_timestamp() where id=target_id;
 perform public.club_audit_event(case when archive then 'CONTENT_ARCHIVED' else 'CONTENT_PUBLISHED' end,target_id);
end $$;

-- Only the trusted Workspace gateway can resolve NAS paths. Clients receive
-- selected document metadata; arbitrary IDs or paths cannot obtain signatures.
create function public.club_media_paths(document_ids uuid[],viewer_auth_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
begin
 if cardinality(document_ids)>40 then raise exception 'Troppi materiali richiesti.';end if;
 perform set_config('request.jwt.claim.sub',coalesce(viewer_auth_id::text,''),true);
 perform set_config('request.jwt.claim.role',case when viewer_auth_id is null then 'anon' else 'authenticated' end,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',viewer_auth_id,'role',case when viewer_auth_id is null then 'anon' else 'authenticated' end)::text,true);
 return coalesce((select jsonb_object_agg(d.id,d.percorso) from public.documenti_workspace d where d.id=any(document_ids) and d.attivo and (
 exists(select 1 from public.club_catalog_product_media m join public.club_catalog_products c on c.product_id=m.product_id join public.prodotti p on p.id=c.product_id where m.document_id=d.id and c.visible and public.club_catalog_eligible(p))
 or exists(select 1 from public.club_post_media m join public.club_posts p on p.id=m.post_id where m.document_id=d.id and p.status='published' and p.starts_at<=now() and (p.ends_at is null or p.ends_at>now()) and p.audience=any(public.club_content_audiences())))),'{}');
end $$;
revoke all on function public.club_media_paths(uuid[],uuid) from public,anon,authenticated;
grant execute on function public.club_media_paths(uuid[],uuid) to service_role;

do $$declare f record;begin
 for f in select p.oid::regprocedure as signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('club_catalog_eligible','club_content_audiences','club_catalog_categories','club_catalog_products','club_catalog_product_json','club_catalog_product','club_post_json','club_feed','club_post','club_editor_data','club_editor_entry','club_editor_media','club_editor_products','club_validate_media','club_save_catalog_product','club_save_post','club_publish_post') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname in ('club_catalog_categories','club_catalog_products','club_catalog_product','club_feed','club_post') then execute format('grant execute on function %s to anon,authenticated',f.signature);
  elsif f.proname in ('club_editor_data','club_editor_entry','club_editor_media','club_editor_products','club_save_catalog_product','club_save_post','club_publish_post') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$;
do $$declare original text;revised text;begin
 select pg_get_functiondef('public.club_api_boundary()'::regprocedure) into original;
 revised:=replace(original,'''/rpc/club_public_info''','''/rpc/club_public_info'',''/rpc/club_catalog_categories'',''/rpc/club_catalog_products'',''/rpc/club_catalog_product'',''/rpc/club_feed'',''/rpc/club_post''');
 if revised=original then raise exception 'Unexpected Club API boundary.';end if;execute revised;
 select pg_get_functiondef('public.club_session()'::regprocedure) into original;
 revised:=replace(original,'''regolamento'']','''regolamento'',''catalogo'',''contenuti'']');
 if revised=original then raise exception 'Unexpected Club session permission list.';end if;execute revised;
end $$;

